class BalanceSheet:
    def __init__(self):
        self.assets = {'cash_and_cash_equivalents': None, 'total_current_assets': None}
        self.liabilities = {'total_current_liabilities': None}

    def load_balance_sheet(self, data: dict) -> bool:
        # Load balance sheet from the provided dictionary and update attributes accordingly.
        if not isinstance(data, dict):
            return False

        for key in ['cash_and_cash_equivalents', 'total_current_assets']:
            self.assets[key] = data.get(key)
        self.liabilities['total_current_liabilities'] = data.get('total_current_liabilities')
        return True

    def get_net_debt(self) -> int:
        cash_and_cash_eq = self.assets['cash_and_cash_equivalents'] if self.assets['cash_and_cash_equivalents'] is not None else 0
        total_current_assets = self.assets['total_current_assets'] if self.assets['total_current_assets'] is not None else 0
        total_current_liabilities = self.liabilities['total_current_liabilities'] if self.liabilities['total_current_liabilities'] is not None else 0

        net_debt = (total_current_liabilities - cash_and_cash_eq)
        return max(0, net_debt) # Ensure the value of net debt is non-negative since we're calculating current liabilities minus cash equivalents.

class FinancialDataProcessor:
    def __init__(self):
        self.balance_sheet = BalanceSheet()

    def extract_financial_data(self, financial_info: dict, year: int) -> None:
        # Extract specific balance sheet items for the given fiscal year and load them into the BalanceSheet object.
        relevant_year_key = f'September {1 if year == 2024 else 3}, {year}'

        cash_and_cash_eq = financial_info['assets']['CURRENT ASSETS'].get('Cash and cash equivalents', {}).get(relevant_year_key, None)
        total_current_assets = financial_info['assets']['TOTAL ASSETS'][relevant_year_key]
        total_current_liabilities = financial_info['liabilities']['CURRENT LIABILITIES'][relevant_year_key]

        self.balance_sheet.load_balance_sheet({'cash_and_cash_equivalents': cash_and_cash_eq, 'total_current_assets': total_current_assets, 'total_current_liabilities': total_current_liabilities})

    def compute_net_debt(self) -> int:
        return self.balance_sheet.get_net_debt()

